import ActionButtons from './ActionButtons';
import Link from 'next/link';

// src/app/page.tsx

// Fungsi untuk narik data dari Backend (NestJS)
async function getWisata() {
  // Panggil URL dari .env.local lu
  const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/wisata`, {
    cache: 'no-store', // Biar datanya selalu fresh setiap kali halaman di-refresh
  });

  if (!res.ok) {
    throw new Error('Gagal menarik data dari API');
  }

  return res.json();
}

export default async function Dashboard() {
  // Eksekusi penarikan data
  const dataWisata = await getWisata();

  return (
    <main className="p-10 min-h-screen bg-gray-50 text-gray-800">
      <div className="max-w-5xl mx-auto">
        <h1 className="text-3xl font-bold mb-8 text-blue-900">Dashboard Admin Pahawang</h1>
        
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold">Daftar Destinasi Wisata</h2>
            <Link 
  href="/tambah" 
  className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition"
>
  + Tambah Destinasi
</Link>
          </div>
          
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b-2 border-gray-200 bg-gray-50">
                  <th className="py-3 px-4 text-sm font-semibold text-gray-600 rounded-tl-lg">ID</th>
                  <th className="py-3 px-4 text-sm font-semibold text-gray-600">Nama Tempat</th>
                  <th className="py-3 px-4 text-sm font-semibold text-gray-600">Lokasi</th>
                  <th className="py-3 px-4 text-sm font-semibold text-gray-600 text-right rounded-tr-lg">Aksi</th>
                </tr>
              </thead>
              <tbody>
                {dataWisata.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="py-4 text-center text-gray-500">
                      Belum ada data wisata.
                    </td>
                  </tr>
                ) : (
                  dataWisata.map((item: any) => (
                    <tr key={item.id} className="border-b border-gray-100 hover:bg-gray-50 transition">
                      <td className="py-3 px-4 text-gray-600">#{item.id}</td>
                      <td className="py-3 px-4 font-medium text-gray-900">{item.nama}</td>
                      <td className="py-3 px-4 text-gray-600">{item.lokasi}</td>
                      <td className="py-3 px-4 text-right space-x-3">
                        <button className="text-blue-500 hover:underline text-sm">Edit</button>
                        <button className="text-red-500 hover:underline text-sm">Hapus</button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </main>
  );
}